/// The degree-1 coefficients of the main field, IGRF-13 at 2020.0 (matlab_sils/data/igrf13coeffs.txt),
/// until the igrf14 bundle lands (docs/ADCS_GAPS.md).
pub const IGRF_G10: f64 = -0.0000294048;

pub const IGRF_G11: f64 = -0.0000014509000000000002;

pub const IGRF_H11: f64 = 0.0000046525;

/// The dipole strength B0 = sqrt(g10^2 + g11^2 + h11^2) and its tilt from the spin axis.
/// - returns b0: real[T] (passed in kg/(s^2 A))
/// - returns tilt: real[rad] (passed a plain number)
#[allow(clippy::too_many_arguments)]
pub fn dipole() -> (f64, f64) {
    let mut b0: f64 = 0.0;
    let mut tilt: f64 = 0.0;
    b0 = f64::sqrt(((rt::ipow(crate::env::IGRF_G10, 2) + rt::ipow(crate::env::IGRF_G11, 2)) + rt::ipow(crate::env::IGRF_H11, 2)));
    tilt = f64::acos(((-(crate::env::IGRF_G10)) / b0));
    (b0, tilt)
}

/// The dipole field at the magnetic equator at radius r: B_min = B0 (R_E/r)^3.
/// - r: real[km] (passed in m)
/// - returns b_min: real[T] (passed in kg/(s^2 A))
#[allow(clippy::too_many_arguments)]
pub fn dipole_field_equator(r: f64) -> f64 {
    let mut b_min: f64 = 0.0;
    let (mut b0, mut tilt) = crate::env::dipole();
    b_min = (b0 * rt::ipow((crate::env::R_E / r), 3));
    b_min
}

/// The node's answer, B_min, as dipole_field_equator gives it.
