/// The static exponential atmosphere (Vallado 2013, table 8-4; the engine's atmos.rs):
/// base altitude, base density, scale height.
/// Table (step): h -> h0, rho0, scale.
pub fn atmosphere(h: f64) -> (f64, f64, f64) {
    let r = rt::lookup_step(&TABLE_ATMOSPHERE, h);
    (r[0], r[1], r[2])
}

/// The neutral density at altitude h: rho0 exp(-(h - h0)/H) in the table's band. The epoch does not
/// enter yet: the solar-activity dependence waits on the nrlmsis2 bundle (docs/ADCS_GAPS.md).
/// - h: real[km] (passed in m)
/// - t_epoch: real[yr] (passed in s)
/// - returns rho: real[kg/m^3] (passed in kg/m^3)
#[allow(clippy::too_many_arguments)]
pub fn density_at(h: f64, t_epoch: f64) -> f64 {
    let mut rho: f64 = 0.0;
    let (mut h0, mut rho0, mut scale) = crate::env::atmosphere(h);
    rho = (rho0 * f64::exp(((-((h - h0))) / scale)));
    rho
}

/// The speed on a circular orbit of radius r: v = sqrt(mu/r).
/// - r: real[km] (passed in m)
/// - returns v: real[m/s] (passed in m/s)
#[allow(clippy::too_many_arguments)]
pub fn circular_speed(r: f64) -> f64 {
    let mut v: f64 = 0.0;
    v = f64::sqrt((crate::env::MU_E / r));
    v
}

/// The Earth-Sun distance in AU at a time from J2000.0 (Vallado 2013, algorithm 29).
/// - t_epoch: real[yr] (passed in s)
/// - returns d: real[1] (passed a plain number)
#[allow(clippy::too_many_arguments)]
pub fn sun_distance_au(t_epoch: f64) -> f64 {
    let mut d: f64 = 0.0;
    let mut tc: f64 = (t_epoch / 3155760000.0);
    let mut m: f64 = ((357.5291092 + (35999.05034 * tc)) * 0.017453292519943295);
    d = ((1.000140612 - (0.016708617 * f64::cos(m))) - (0.000139589 * f64::cos((2.0 * m))));
    d
}

/// Total solar irradiance at 1 AU (Kopp & Lean 2011, 1360.8 +- 0.5 W/m^2). source: kopp2011
pub const F_SUN: f64 = 1360.8;

/// The speed of light (exact, SI).
pub const C_LIGHT: f64 = 299792458.0;

/// The Sun's radiation pressure at the Earth's distance: P = (F_sun/c) (1 AU/d)^2.
/// - t_epoch: real[yr] (passed in s)
/// - returns p_srp: real[Pa] (passed in kg/(m s^2))
#[allow(clippy::too_many_arguments)]
pub fn solar_pressure(t_epoch: f64) -> f64 {
    let mut p_srp: f64 = 0.0;
    let mut d: f64 = crate::env::sun_distance_au(t_epoch);
    p_srp = ((crate::env::F_SUN / crate::env::C_LIGHT) / rt::ipow(d, 2));
    p_srp
}

/// The node's answer, P_srp, as solar_pressure gives it.
/// - t_epoch: real[yr] (passed in s)
/// - returns P_srp: real[Pa] (passed in kg/(m s^2))
#[allow(clippy::too_many_arguments)]
pub fn m3_5(t_epoch: f64) -> f64 {
    let mut P_srp: f64 = 0.0;
    P_srp = crate::env::solar_pressure(t_epoch);
    P_srp
}
